using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 4, Name = "English", Abbreviation = "ENG" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" },
    ];

    private static readonly List<Course> Courses =
    [
        new()
        {
            Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming",
            Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, data structures, and basic object-oriented programming.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science",
            InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has 15 years of teaching experience. Her research focuses on programming language education and CS pedagogy.",
            IsFeatured = true
        },
        new()
        {
            Id = 2, CourseCode = "CS 301", Title = "Data Structures and Algorithms",
            Description = "Advanced study of data structures (trees, graphs, hash tables) and algorithm design (sorting, searching, dynamic programming). Includes analysis of time and space complexity.",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentId = 1, DepartmentName = "Computer Science",
            InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez is an ACM Distinguished Educator with publications in algorithm optimization. He previously worked at Google Research.",
            IsFeatured = true
        },
        new()
        {
            Id = 3, CourseCode = "CS 450", Title = "Machine Learning",
            Description = "Introduction to machine learning techniques including supervised and unsupervised learning, neural networks, and model evaluation. Hands-on projects with real-world datasets.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = 1, DepartmentName = "Computer Science",
            InstructorName = "Dr. Aisha Patel", InstructorBio = "Dr. Patel is an AI researcher with industry experience at DeepMind. She specializes in deep learning and natural language processing.",
            IsFeatured = false
        },
        new()
        {
            Id = 4, CourseCode = "MATH 201", Title = "Linear Algebra",
            Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications to computer graphics, data science, and engineering.",
            Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, DepartmentName = "Mathematics",
            InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is a mathematician specializing in applied linear algebra. He has authored two textbooks used at universities worldwide.",
            IsFeatured = true
        },
        new()
        {
            Id = 5, CourseCode = "MATH 301", Title = "Differential Equations",
            Description = "Ordinary differential equations, Laplace transforms, systems of equations, and numerical methods. Applications in physics and engineering.",
            Credits = 4, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 2, DepartmentName = "Mathematics",
            InstructorName = "Dr. Elena Volkov", InstructorBio = "Dr. Volkov earned her doctorate from Cambridge and researches mathematical modeling of complex systems.",
            IsFeatured = false
        },
        new()
        {
            Id = 6, CourseCode = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Covers Newton's laws, energy conservation, rotational dynamics, and introduction to oscillations. Includes weekly lab sessions.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM + Lab Thu 2:00–4:00 PM", DepartmentId = 3, DepartmentName = "Physics",
            InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an experimental physicist who has worked at CERN. He brings real-world physics research into the classroom.",
            IsFeatured = true
        },
        new()
        {
            Id = 7, CourseCode = "PHYS 301", Title = "Quantum Mechanics",
            Description = "Introduction to quantum theory: wave functions, Schrödinger equation, quantum states, operators, and measurement. Prerequisites: PHYS 201, MATH 301.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 3, DepartmentName = "Physics",
            InstructorName = "Dr. Lisa Nakamura", InstructorBio = "Dr. Nakamura is a theoretical physicist whose research spans quantum information and condensed matter theory.",
            IsFeatured = false
        },
        new()
        {
            Id = 8, CourseCode = "ENG 102", Title = "Academic Writing",
            Description = "Develops skills in analytical reading, argumentative writing, research methods, and proper citation. Students produce a portfolio of essays throughout the semester.",
            Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", DepartmentId = 4, DepartmentName = "English",
            InstructorName = "Prof. David Okafor", InstructorBio = "Prof. Okafor is a published author and writing instructor with 20 years of experience teaching composition at the university level.",
            IsFeatured = false
        },
        new()
        {
            Id = 9, CourseCode = "ENG 350", Title = "Modern American Literature",
            Description = "Survey of American literature from 1900 to the present. Examines major movements, authors, and cultural contexts including modernism, the Harlem Renaissance, and postmodernism.",
            Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentId = 4, DepartmentName = "English",
            InstructorName = "Dr. Maria Santos", InstructorBio = "Dr. Santos specializes in 20th-century American fiction and has published extensively on multicultural narratives in contemporary literature.",
            IsFeatured = false
        },
        new()
        {
            Id = 10, CourseCode = "HIST 201", Title = "World History: 1500–Present",
            Description = "Explores global historical developments from the early modern period to today. Topics include colonialism, industrialization, world wars, decolonization, and globalization.",
            Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 5, DepartmentName = "History",
            InstructorName = "Dr. Anthony Walsh", InstructorBio = "Dr. Walsh is a historian of global empires with fieldwork experience across three continents. He brings primary source analysis into every lecture.",
            IsFeatured = false
        },
    ];

    public List<Department> GetDepartments() => Departments;

    public Department? GetDepartment(int id) => Departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = Courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => Courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => Courses.Where(c => c.IsFeatured).ToList();
}

