@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Home - University Course Catalog</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-5 fw-bold">University Course Catalog</h1>
    <p class="lead text-muted">Explore departments, discover courses, and enroll for the upcoming semester.</p>
    <a href="/courses" class="btn btn-primary btn-lg mt-2">Browse All Courses</a>
</div>

<section class="mb-5">
    <h2>Featured Courses</h2>
    <div class="row g-3 mt-2">
        @foreach (var course in featuredCourses)
        {
            <div class="col-md-6 col-lg-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.CourseCode</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@course.Title</h6>
                        <p class="card-text small">@course.Credits credits &middot; @course.DepartmentName</p>
                        <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

<section>
    <h2>Departments</h2>
    <div class="row g-3 mt-2">
        @foreach (var dept in departments)
        {
            <div class="col-md-4 col-lg-3">
                <a href="/courses?departmentId=@dept.Id" class="text-decoration-none">
                    <div class="card text-center p-3 h-100">
                        <h5 class="mb-1">@dept.Abbreviation</h5>
                        <p class="text-muted mb-0 small">@dept.Name</p>
                    </div>
                </a>
            </div>
        }
    </div>
</section>

@code {
    private List<Course> featuredCourses = [];
    private List<Department> departments = [];

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
    }
}

